import { test, describe, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from '../src/server.js'
import { TodoStore } from '../src/store.js'
import { UserStore, seedUsers } from '../src/auth/users.js'
import { hashPassword, needsRehash, verifyPassword, DEFAULT_ITERATIONS } from '../src/auth/passwords.js'

let server
let baseUrl
let users

before(async () => {
  users = seedUsers()
  server = createServer(new TodoStore(), users)
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve))
  baseUrl = `http://127.0.0.1:${server.address().port}`
})

after(async () => {
  server.closeAllConnections()
  await new Promise((resolve) => server.close(resolve))
})

async function login(body) {
  const response = await fetch(`${baseUrl}/auth/login`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  })
  return { status: response.status, body: await response.json() }
}

function iterationsOf(stored) {
  return Number.parseInt(stored.split('$')[2], 10)
}

describe('密码哈希', () => {
  test('R3.S1 新哈希使用 600000 次迭代', () => {
    assert.equal(DEFAULT_ITERATIONS, 600000)
    const stored = hashPassword('secret', { salt: 'fixed-salt' })
    assert.match(stored, /^pbkdf2\$sha256\$600000\$fixed-salt\$/)
    assert.equal(verifyPassword('secret', stored), true)
    assert.equal(verifyPassword('wrong', stored), false)
  })

  test('R3.S2 旧哈希仍可校验（100000 与 1000 次迭代）', () => {
    for (const iterations of [100000, 1000]) {
      const old = hashPassword('secret', { iterations })
      assert.equal(iterationsOf(old), iterations)
      assert.equal(verifyPassword('secret', old), true)
      assert.equal(verifyPassword('wrong', old), false)
    }
  })

  test('篡改或格式错误的哈希校验失败', () => {
    assert.equal(verifyPassword('secret', 'not-a-hash'), false)
    assert.equal(verifyPassword('secret', 'pbkdf2$sha256$100000$salt$dGFtcGVy'), false)
  })

  test('needsRehash 识别较低迭代次数', () => {
    const old = hashPassword('secret', { iterations: 1000 })
    assert.equal(needsRehash(old), true)
    const current = hashPassword('secret', { iterations: DEFAULT_ITERATIONS })
    assert.equal(needsRehash(current), false)
  })
})

describe('登录接口', () => {
  test('R4.S2 正确邮箱密码返回 200 与用户信息，且不泄露哈希', async () => {
    const res = await login({ email: 'alice@example.com', password: 'alice-secret' })
    assert.equal(res.status, 200)
    assert.equal(res.body.user.id, 'user-1')
    assert.equal(res.body.user.displayName, 'Alice')
    assert.deepEqual(Object.keys(res.body.user).sort(), ['displayName', 'email', 'id'])
    assert.equal('passwordHash' in res.body.user, false)
  })

  test('R4.S3 密码错误返回 401，且与未知邮箱不可区分', async () => {
    const wrongPassword = await login({ email: 'alice@example.com', password: 'nope' })
    const unknownEmail = await login({ email: 'nobody@example.com', password: 'nope' })
    assert.equal(wrongPassword.status, 401)
    assert.equal(unknownEmail.status, 401)
    assert.equal(wrongPassword.body.error, unknownEmail.body.error)
  })

  test('R3.S3 旧参数哈希在登录成功后自动迁移到 600000 次迭代', async () => {
    const migrationUsers = new UserStore()
    migrationUsers.add({ id: 'user-9', email: 'carol@example.com', password: 'carol-secret' })
    migrationUsers.replaceHash('user-9', hashPassword('carol-secret', { iterations: 1000 }))
    assert.equal(iterationsOf(migrationUsers.get('user-9').passwordHash), 1000)
    assert.equal(needsRehash(migrationUsers.get('user-9').passwordHash), true)

    const migrationServer = createServer(new TodoStore(), migrationUsers)
    await new Promise((resolve) => migrationServer.listen(0, '127.0.0.1', resolve))
    const url = `http://127.0.0.1:${migrationServer.address().port}/auth/login`
    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ email: 'carol@example.com', password: 'carol-secret' }),
      })
      assert.equal(response.status, 200)
      await response.json()
      const stored = migrationUsers.get('user-9').passwordHash
      assert.equal(iterationsOf(stored), 600000)
      assert.equal(needsRehash(stored), false)
      assert.equal(verifyPassword('carol-secret', stored), true)
    } finally {
      migrationServer.closeAllConnections()
      await new Promise((resolve) => migrationServer.close(resolve))
    }
  })

  test('R4.S1 失败登录不触发迁移，旧哈希保持原值', async () => {
    const failedUsers = new UserStore()
    failedUsers.add({ id: 'user-10', email: 'dave@example.com', password: 'dave-secret' })
    const original = hashPassword('dave-secret', { iterations: 1000 })
    failedUsers.replaceHash('user-10', original)

    const failedServer = createServer(new TodoStore(), failedUsers)
    await new Promise((resolve) => failedServer.listen(0, '127.0.0.1', resolve))
    const url = `http://127.0.0.1:${failedServer.address().port}/auth/login`
    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ email: 'dave@example.com', password: 'wrong-secret' }),
      })
      assert.equal(response.status, 401)
      await response.json()
      assert.equal(failedUsers.get('user-10').passwordHash, original)
      assert.equal(iterationsOf(failedUsers.get('user-10').passwordHash), 1000)
    } finally {
      failedServer.closeAllConnections()
      await new Promise((resolve) => failedServer.close(resolve))
    }
  })
})

